import { Group, Mesh, PlaneGeometry, CircleGeometry, CylinderGeometry, TorusKnotGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, DirectionalLight, AmbientLight, Color } from 'three/webgpu';
import { uv, mix, length, smoothstep, oneMinus, vec2, float, color, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group: _Group } = ctx.THREE;
  const root = new _Group();

  // -------------------- Helpers & State --------------------
  const disposables = [];
  const primitiveInstances = [];

  function registerDisposable(obj) {
    disposables.push(obj);
  }

  // -------------------- Backdrop (gradient plane) --------------------
  const backdropGeom = new PlaneGeometry(7, 6);
  const gradientStops = (config?.visualSpec?.gradientStops ??
    [
      { at: 0, hex: '#0b0b10' },
      { at: 0.7, hex: '#101017' },
      { at: 1, hex: '#16161d' },
    ]);
  // Assume exactly three stops for brevity
  const c0 = color(gradientStops[0].hex);
  const c1 = color(gradientStops[1].hex);
  const c2 = color(gradientStops[2].hex);
  const v = uv().y;
  const mix01 = mix(c0, c1, smoothstep(gradientStops[0].at, gradientStops[1].at, v));
  const backdropColorNode = mix(mix01, c2, smoothstep(gradientStops[1].at, gradientStops[2].at, v));
  const backdropMat = new MeshStandardNodeMaterial({ color: backdropColorNode });
  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -3);
  root.add(backdropMesh);
  registerDisposable(backdropMat);

  // -------------------- Pedestal Cylinder --------------------
  const pedRadius = 1.1;
  const pedHeight = 0.5;
  const pedGeom = new CylinderGeometry(pedRadius, pedRadius, pedHeight, 32);
  const pedMat = new MeshStandardNodeMaterial({
    color: new Color('#14141a'),
    roughness: float(0.7),
    metalness: float(0.35),
  });
  const pedMesh = new Mesh(pedGeom, pedMat);
  // Position so top face is at y = -0.35
  const pedCenterY = -0.35 - pedHeight / 2;
  pedMesh.position.set(0, pedCenterY, 0);
  root.add(pedMesh);
  registerDisposable(pedMat);

  // -------------------- Contact Shadow (radial gradient) --------------------
  const shadowGeom = new CircleGeometry(1.5, 64);
  const uvPos = uv(); // uv ranges 0..1
  const dist = length(uvPos.sub(vec2(0.5)));
  const opacityNode = float(0.6).mul(oneMinus(smoothstep(0.0, 0.4, dist)));
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(0x000000),
    opacity: opacityNode,
    transparent: true,
    depthWrite: false,
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -0.36, 0);
  root.add(shadowMesh);
  registerDisposable(shadowMat);

  // -------------------- Torus Knot --------------------
  const knotGeom = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial({
    color: new Color('#ffffff'),
    roughness: float(0.55),
    metalness: float(0.55),
    clearcoat: float(0.22),
    clearcoatRoughness: float(0.35),
    anisotropy: float(0.9),
    anisotropyRotation: float(Math.PI / 2),
  });
  const knotMesh = new Mesh(knotGeom, knotMat);
  knotMesh.position.set(0, 0.4, 0);
  root.add(knotMesh);
  registerDisposable(knotMat);

  // Load brushed metal texture and assign as map
  if (config?.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      knotMat.map = tex;
      knotMat.needsUpdate = true;
      registerDisposable(tex);
    });
  }

  // -------------------- Lights --------------------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2, 2);
  root.add(keyLight);

  const rimLight = new DirectionalLight(new Color('#ff2a38'), 0.6);
  rimLight.position.set(-2, 1, -2);
  root.add(rimLight);

  // -------------------- Text --------------------
  const items = config?.textContent ?? config?.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const isHeadline = item.role === 'headline' || (item.typography && item.typography.fontSize >= 60);
    const opts = {
      fontSize: item.typography?.fontSize ?? (isHeadline ? 68 : 18),
      color: isHeadline ? '#e8ecf2' : '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text ?? '', opts);
    const yOffset = isHeadline ? -1.2 : -1.6;
    txt.position.set(0, yOffset, 0);
    root.add(txt);
    // No explicit cleanup needed; text objects will be disposed with group disposal.
  }

  // -------------------- Cinematic Primitives --------------------
  const primitivesList = config?.cinematicPrimitives ?? [];
  for (const prim of primitivesList) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const instance = fn(root, prim.params ?? {});
      primitiveInstances.push(instance);
    }
  }

  // -------------------- User Data --------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose disposables
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
      if (d && typeof d.dispose === 'function') d.dispose();
      if (d && d instanceof THREE.Texture && typeof d.dispose === 'function') d.dispose();
    }
    // Cleanup primitives
    for (const p of primitiveInstances) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    // Kill any GSAP timelines attached to this node (if any)
    gsap.killTweensOf(root);
  };

  return root;
}
